insert into public.sections (page_id, key, type, tone, data, position) select id, 'traditional', 'pricingCards', 'surface', '{"eyebrow":"Traditional SEO","heading":"Traditional SEO Packages","body":"Three tiers, sized by footprint rather than by headcount.","packageIds":["traditional-regional","traditional-national","traditional-national-plus"],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 4 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'included', 'cardGrid', 'white', '{"variant":"compact","columns":3,"eyebrow":"Every Tier","heading":"Included in Every Package","body":"Tiers differ by volume, not by what is included.","groupLabels":[{"at":0,"label":"Local SEO, all tiers"},{"at":6,"label":"Traditional SEO, all tiers"}],"cards":[{"title":"SEO Strategy & Roadmap","icon":"compass","body":"A plan for the quarter, with the reasoning behind the order."},{"title":"Content & On-Page Optimization","icon":"pencil","body":"Service pages, titles, descriptions and page structure."},{"title":"Technical Monitoring","icon":"gauge","body":"Crawling, indexing and site health watched month to month."},{"title":"Detailed Monthly Reporting","icon":"bar-chart","body":"What was tracked, what moved, and what did not."},{"title":"Monthly Project Recap","icon":"message-square","body":"Delivered by Loom or a video call, with room to ask questions."},{"title":"Review Management","icon":"star","body":"Requests sent to real customers, and replies to what arrives."},{"title":"SEO Strategy & Roadmap","icon":"compass","body":"The same plan, applied across markets rather than an area."},{"title":"Strategic SEO Pages","icon":"file-text","body":"Pages built for specific searches, produced to a schedule."},{"title":"Technical Monitoring","icon":"gauge","body":"Issues flagged as they appear, not found in an annual audit."},{"title":"Reporting & Monthly Recap","icon":"bar-chart","body":"Dashboard reporting alongside the recap, in both cases explained."},{"title":"Authority-Building Recommendations","icon":"network","body":"Advice on what would strengthen authority. Recommendations, not link placements."}]}'::jsonb, 5 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'onboarding', 'featureSplit', 'surface', '{"align":"left","eyebrow":"The One-Time Fee","heading":"What Onboarding Covers","body":"Every tier carries a one-time onboarding fee, from $349 to $1,295 depending on the package. It pays for the work that has to happen once before the monthly work means anything: nothing built on an unaudited foundation is worth reporting on.\n\nThe two scopes are genuinely different rather than one generic setup with different price tags, which is why they are listed separately below. A Launch Sprint can waive this fee entirely, which the next section sets out.","tableHeadings":["Lane","Onboarding covers"],"tableRows":[{"cells":["Local SEO","Audit, setup, tracking, foundational optimization, and local visibility setup"]},{"cells":["Traditional SEO","Audit, setup, tracking, foundational optimization, and roadmap development"]}],"groups":[],"cta":{"label":"See how a sprint waives it","href":"#sprint-waiver"}}'::jsonb, 6 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'sprint-waiver', 'waiverMatrix', 'white', '{"eyebrow":"Another Way In","heading":"Start With a Launch Sprint","body":"A sprint is the onboarding work done standalone, with a roadmap attached. That is why the waiver exists rather than being a discount: it is close to the same job, bought once, with no monthly commitment behind it.","sprintHeading":"Sprint","priceHeading":"One-time","waivesHeading":"Waives onboarding on","rows":[{"sprint":"Neighborhood Launch Sprint","price":"$799","waives":"Neighborhood, Citywide, or Metro"},{"sprint":"Regional Launch Sprint","price":"$1,495","waives":"Regional"},{"sprint":"National Launch Sprint","price":"$2,295","waives":"National or National+"}],"condition":"Monthly service must begin within 30 calendar days of sprint completion.","cta":{"label":"View Launch Sprints","href":"/launch-sprints"}}'::jsonb, 7 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'surface', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"Included in every package in both lanes, at every tier.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 8 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Pricing Questions","items":[{"question":"Why a 12-month term?","answer":"Because SEO compounds and a short engagement cannot show what a full one can. Most of the foundational work lands in the first quarter and most of the return on it arrives later, so a three-month contract would mean paying for the setup and leaving before the benefit. The term applies to all six monthly tiers in both lanes."},{"question":"What happens after 12 months?","answer":"It runs month to month from then on, for as long as you want it to, and either side can end it with 30 days written notice. There is no second term and no automatic re-commitment."},{"question":"What does the onboarding fee cover?","answer":"On Local: the audit, tracking setup, foundational optimization and the local visibility setup, meaning profile, categories, services, citations and the grid baseline. On Traditional: the audit, tracking setup, foundational optimization and roadmap development. A Launch Sprint can waive it entirely if monthly service begins within 30 days of the sprint finishing."},{"question":"Can tiers be changed later?","answer":"Upgrades happen any time. The deliverables adjust from the next cycle and there is no additional onboarding fee. Downgrades take effect at renewal rather than mid-term."},{"question":"Which lane fits?","answer":"Reach decides it, not size. A business competing for customers in a defined area is Local, however many locations it runs there. A business competing across markets, service lines or competitive search is Traditional. Both service pages set out the difference in more detail."},{"question":"Does this include blog content?","answer":"Yes. Strategic SEO Pages covers all written SEO content, blog posts included. Early phases usually prioritise local and industry pages first, simply because blog content needs somewhere to point before it does much good."},{"question":"What is not included?","answer":"Paid advertising, web design and development, social media posting, and link building. Authority building is covered as recommendations rather than as placements bought on your behalf."},{"question":"Is there anything without a term?","answer":"Launch Sprints. One-time, completed within 30 days, no term and no renewal, ending with a roadmap that is yours whatever you decide next."},{"question":"Can Local and Traditional be combined?","answer":"Yes, as a custom plan. It is usually scoped from the Local deliverable side with the Traditional work layered on, and it needs a conversation rather than a package number."},{"question":"What if none of these fit?","answer":"Larger or more involved scopes get a custom quote. That is a real answer rather than a polite one: several kinds of engagement genuinely do not fit into three tiers."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 9 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Not Sure Which One Fits?","body":"A visibility review covers where you appear now, what is holding it back, and which package or sprint actually matches the problem.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Launch Sprints","href":"/launch-sprints"}}'::jsonb, 10 from public.pages where slug = '/monthly-seo-packages';

-- Launch Sprints
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Launch Sprints","heading":"A Fixed Scope, Finished in Thirty Days","body":"A Launch Sprint is a single engagement with a defined start, a defined end, and a written list of everything included. There is no term, no renewal, and no obligation to continue afterwards.","primaryCta":{"label":"Request a Sprint Consultation","href":"/contact?type=sprint"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"roadmap","label":"Thirty days","title":"The Sprint","items":["Audit","Implementation","Handoff","30-Day Action Roadmap"]},{"kind":"coverage","label":"Three sprints","title":"Sized by Reach","items":["Neighborhood","Regional","National"]}]}'::jsonb, 0 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'what-a-sprint-is', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"The Shape of It","heading":"What a Sprint Is","body":"Three things, and they are the whole of the commitment.","cards":[{"title":"One-Time","icon":"rocket","body":"A single engagement. No term, no renewal, and no ongoing invoice arriving next month."},{"title":"Thirty Days","icon":"calendar","body":"A defined window with a defined end. The work is completed inside it rather than running until somebody stops it."},{"title":"Fixed Scope","icon":"list-checks","body":"The deliverable list is the whole list, agreed before anything starts. What is on it gets done, and it is written down."}]}'::jsonb, 1 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'where-it-ends', 'cardGrid', 'white', '{"variant":"numbered","columns":3,"eyebrow":"The Boundary","heading":"Where a Sprint Ends","body":"Being precise about where a fixed-scope engagement stops is the same principle as reporting honestly. It just applies to scope instead.","cards":[{"title":"The List Is the Scope","body":"Everything included is written down before the work begins. Anything outside it is quoted separately rather than absorbed quietly or dropped without mention."},{"title":"Thirty Days, Then Done","body":"The window closes. There is no rollover into an open-ended timeline and no month four that nobody agreed to."},{"title":"A Foundation, Not a Campaign","body":"A sprint builds the base and hands over a roadmap. Ongoing growth is a separate decision, made afterwards with the roadmap in hand."}]}'::jsonb, 2 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'sprints', 'pricingCards', 'surface', '{"eyebrow":"The Three Sprints","heading":"Three Sprints, Sized by Reach","body":"Neighborhood is local work. Regional and National are technical and on-page work across markets. That is a difference in kind rather than in size, so none of the three is a step up from another.","packageIds":["sprint-neighborhood","sprint-regional","sprint-national"]}'::jsonb, 3 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'process', 'processSteps', 'white', '{"eyebrow":"Inside the Window","heading":"What Happens During the Sprint","steps":[{"title":"Audit","body":"The current foundation is reviewed end to end, the priority issues are identified and ranked, and the first fixes are confirmed with you before any of them happen."},{"title":"Implementation","body":"The included setup and optimization work is completed inside the agreed scope. Anything found along the way that sits outside it is flagged and quoted rather than absorbed."},{"title":"Handoff","body":"A clear roadmap with next-step recommendations in priority order, and a clean path into monthly service if that is what you decide to do."}]}'::jsonb, 4 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'waiver', 'waiverMatrix', 'surface', '{"eyebrow":"Continuing On","heading":"Continuing Into Monthly Service","body":"The sprint deliverables and the onboarding work on a monthly package are close to the same job. That is why the waiver exists: a sprint is the onboarding done standalone, with a roadmap attached.","sprintHeading":"Sprint","waivesHeading":"Waives onboarding on","rows":[{"sprint":"Neighborhood","waives":"Neighborhood, Citywide, or Metro"},{"sprint":"Regional","waives":"Regional"},{"sprint":"National","waives":"National or National+"}],"condition":"Monthly service must begin within 30 calendar days of sprint completion.","cta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 5 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'roadmap', 'cardGrid', 'white', '{"variant":"cards","columns":4,"emphasis":true,"eyebrow":"The Deliverable","heading":"What You Walk Away With","body":"The 30-Day Action Roadmap is the thing the sprint is actually for. Everything else is the work that makes it worth reading.","cards":[{"title":"Priority Findings","icon":"search","body":"What is holding visibility back, ranked by impact rather than listed in the order it was found."},{"title":"Completed Work","icon":"clipboard-check","body":"Everything done during the sprint, itemised, so there is no gap between what was paid for and what is visible."},{"title":"Recommended Next Steps","icon":"compass","body":"What to do next, in order, with the reasoning behind the order rather than just the list."},{"title":"A Clear Path Forward","icon":"target","body":"Whether that means monthly service or handling the roadmap internally. Both are real answers, and the roadmap is written to work either way."}],"cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 6 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Sprint Questions","items":[{"question":"Is there any ongoing commitment?","answer":"None. A sprint is a one-time engagement with no term and no auto-renewal. When the 30 days are up, the work is delivered and the arrangement is over unless you decide otherwise."},{"question":"What happens after the 30 days?","answer":"The 30-Day Action Roadmap is handed over, along with everything completed during the sprint. Continuing into monthly service is optional and is a separate decision."},{"question":"How does the onboarding waiver work?","answer":"If monthly service starts within 30 calendar days of the sprint finishing, the onboarding fee on the matching package is waived. The Neighborhood sprint covers Neighborhood, Citywide or Metro; Regional covers Regional; National covers National or National+."},{"question":"Which sprint fits?","answer":"Neighborhood is local work, including the Google Business Profile, citations and a local grid baseline. Regional and National are technical and on-page work across multiple markets. The difference is what a business competes in, not how large it is."},{"question":"Can the roadmap be handled internally?","answer":"Yes. It is written to be actionable by whoever ends up doing it, and plenty of businesses take it and run it themselves. That is a legitimate outcome rather than a failed one."},{"question":"Is a sprint required before monthly service?","answer":"No. It is one route in, not a gate. Monthly packages can start directly, with the standard onboarding fee."}],"cta":{"label":"Request a Sprint Consultation","href":"/contact?type=sprint"}}'::jsonb, 7 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Sprint","body":"A fixed scope, thirty days, and a roadmap at the end of it that is yours whatever you decide to do next.","primaryCta":{"label":"Request a Sprint Consultation","href":"/contact?type=sprint"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 8 from public.pages where slug = '/launch-sprints';

-- About JMC
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroCentered', NULL, '{"eyebrow":"About JMC","heading":"Practical SEO, Explained in Plain English","body":"Jordan Marketing Consultants is a Houston-area SEO agency rooted in League City, helping local, regional, and industry-focused businesses improve search visibility through practical SEO strategy, content planning, local optimization, and clear reporting.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 0 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'approach', 'cardGrid', 'white', '{"variant":"split","eyebrow":"How We Work","heading":"SEO Should Be Understandable Before It Is Impressive","body":"Most businesses that have hired an SEO agency before describe the same experience: work happened, invoices arrived, and nobody could explain what changed. JMC is built around fixing that.","columns":3,"cards":[{"title":"Scope Before Work","icon":"list-checks","body":"You know what is included before anything starts. No discovering the boundaries of your package three months in."},{"title":"Roadmap Over Tasks","icon":"compass","body":"Work is sequenced against a documented plan tied to your goals, not pulled from a generic monthly checklist."},{"title":"Reporting You Read","icon":"bar-chart","body":"A Monthly Recap in plain language, delivered by Loom or a call, so you can ask questions instead of decoding a dashboard."}]}'::jsonb, 1 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'houston', 'fullWidthText', 'surface', '{"eyebrow":"Houston-Area SEO Agency","heading":"Rooted in League City. Built for Houston-Area Growth.","body":"JMC is based in League City and works with businesses across the Greater Houston area and beyond. Being local matters for understanding a market, but it is not a boundary. Traditional SEO clients compete regionally and nationally, and the work is built around where your customers actually are.","cta":{"label":"Explore SEO Services","href":"/local-seo-services"}}'::jsonb, 2 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'specialties', 'cardGrid', 'white', '{"eyebrow":"What We Focus On","heading":"Two Service Lanes, One Standard","body":"Different markets need different strategies. The commitment to clear scope, documented priorities, and honest reporting does not change between them.","columns":2,"cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses that need visibility in a defined city or service area.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"trending-up","body":"For businesses competing across regions, national markets, or specialized industries.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'process', 'processSteps', 'surface', '{"eyebrow":"The Process","heading":"A Clear SEO Process From Review to Recap","body":"The same four steps run every engagement, whether it is a local campaign or a national one.","steps":[{"title":"Visibility Review","body":"We review where your business currently shows up, where visibility is weak, and which opportunities are worth prioritizing."},{"title":"SEO Roadmap","body":"We organize the work around keyword priorities, content needs, local visibility, technical issues, and business goals."},{"title":"Implementation","body":"We complete the scoped SEO work, content updates, local optimization, and technical improvements tied to the plan."},{"title":"Monthly Recap","body":"You receive a clear summary of what was completed, what changed, and what should happen next."}],"cta":{"label":"Start with a Visibility Review","href":"/contact"}}'::jsonb, 4 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Let''s Look at Where Your Visibility Stands","body":"A Visibility Review is the starting point for every JMC engagement, and it is useful even if you decide not to work with us.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 5 from public.pages where slug = '/about';

-- Resources
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroCentered', NULL, '{"eyebrow":"Resources","heading":"SEO, Explained Without the Jargon","body":"Straight answers to the questions business owners actually ask about search visibility. We are building this out as we go. If something you need is missing, ask us directly.","primaryCta":{"label":"Ask an SEO Question","href":"/contact"},"secondaryCta":{"label":"View SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 0 from public.pages where slug = '/resources';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'topics', 'cardGrid', 'white', '{"variant":"compact","eyebrow":"Topics","heading":"What We Write About","body":"The areas where clear information saves businesses the most money.","columns":3,"cards":[{"title":"Local Search","icon":"map-pin","body":"How Google Business Profile, reviews, citations, and local content actually influence whether you show up nearby."},{"title":"Organic Search Strategy","icon":"trending-up","body":"How keyword strategy, content structure, and technical health work together across larger markets."},{"title":"SEO Reporting","icon":"bar-chart","body":"What to expect from an agency report, and the questions worth asking when something looks vague."},{"title":"Real Estate SEO","icon":"home","body":"How agents, teams, and brokerages build neighborhood visibility that compounds over time."},{"title":"Technical SEO","icon":"wrench","body":"The structural issues that quietly cap visibility, and how to tell whether yours are serious."},{"title":"AI and Answer Engines","icon":"search","body":"How search behavior is shifting, and which SEO fundamentals matter more because of it."}]}'::jsonb, 1 from public.pages where slug = '/resources';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'ai-search', 'featureSplit', 'surface', '{"eyebrow":"Search Is Changing","heading":"SEO Built for How People Search Now","body":"People search across Google, maps, organic results, and increasingly AI-powered answer tools. Nobody can guarantee placement inside an AI answer, and you should be skeptical of anyone who says otherwise. What does help is the same practical work that has always helped: clear service pages, strong site structure, sound internal linking, accurate schema, and content that establishes what you do and where you do it.","cta":{"label":"Talk Through Your SEO Strategy","href":"/contact"},"groups":[{"title":"Clear Service Pages","icon":"file-text","body":"Unambiguous answers about what you offer and to whom."},{"title":"Site Structure","icon":"network","body":"Organization that makes relationships between services obvious."},{"title":"Schema and Entities","icon":"layers","body":"Structured data that states who you are and where you work."},{"title":"Topical Authority","icon":"shield-check","body":"Depth in your actual subject area rather than thin coverage everywhere."}]}'::jsonb, 2 from public.pages where slug = '/resources';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'articles', 'postList', 'surface', '{"eyebrow":"Articles","heading":"Latest From the Resources Hub","body":"Plain-English explainers, written as the questions come up.","limit":6,"emptyMessage":"The first articles are being written now. In the meantime, ask us the question directly. We answer it either way.","cta":{"label":"Ask an SEO Question","href":"/contact"}}'::jsonb, 3 from public.pages where slug = '/resources';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Have a Question We Haven''t Written About Yet?","body":"Ask it directly. If it is useful to you, it is probably useful to other businesses in the same position, and it may well become the next resource here.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 4 from public.pages where slug = '/resources';

-- Link Hub
insert into public.sections (page_id, key, type, tone, data, position) select id, 'links', 'linkStack', NULL, '{"eyebrow":"@htxseo","theme":"dark","heading":"Houston’s SEO Agency","body":"Houston-area SEO. Practical strategy, local optimization, content planning, and reporting you can actually read.","socials":[{"platform":"instagram","href":"https://instagram.com/"},{"platform":"facebook","href":"https://facebook.com/"},{"platform":"linkedin","href":"https://linkedin.com/"}],"links":[{"label":"Request a Visibility Review","href":"/contact","description":"Where you show up now, and what to fix first","icon":"target","featured":true},{"label":"SEO Packages & Pricing","href":"/monthly-seo-packages","description":"Local, traditional, and launch sprints","icon":"layers"},{"label":"Local SEO Services","href":"/local-seo-services","description":"Google Business Profile, citations, local content","icon":"map-pin"},{"label":"SEO Resources","href":"/resources","description":"Plain-English explainers, no jargon","icon":"file-text"},{"label":"Call (281) 989-0468","href":"tel:+12819890468","icon":"message-square"}],"footnote":"League City, TX · Serving the Greater Houston area"}'::jsonb, 0 from public.pages where slug = '/links';

-- SEO Reporting
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"SEO Reporting","heading":"SEO Reporting That Answers Four Questions","body":"Most SEO reporting either buries the work in numbers or skips it entirely. JMC reports every month in the same shape, so you always know what was done, why it was the priority, and what it changed.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Local SEO","href":"/local-seo-services"},"showcase":[{"kind":"report","label":"Every month","title":"Monthly Project Recap","items":["What We Did","Why We Did It","What Changed","Where We''re Headed"]},{"kind":"coverage","label":"Also included","title":"Quarterly Update","items":["Local","Traditional","Every tier"]}]}'::jsonb, 0 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'four-questions', 'fourQuestions', 'surface', '{"eyebrow":"The Shape of It","heading":"The Four Questions Every Recap Answers","body":"The same four headings every month, in the same order, on every package in both service lines.","did":"The actual work completed that month, listed as specific tasks rather than categories. Not “content optimization” but which pages were rewritten, which titles changed, and which listings were corrected.","didExample":"Rewrote service page titles and meta descriptions for four priority pages.","why":"The reasoning behind the order. SEO is a queue of things worth doing, and the useful part of a report is understanding why this month''s work went to the front of it rather than something else.","whyExample":"Those four pages already had impressions and no clear title, so they were the cheapest movement available.","changed":"Movement, reported honestly. Some months show clear change and some show very little, and the recap says which one it was. A report that reads like progress every single month is not a report.","changedExample":"Grid visibility for the primary service term, compared with last month.","next":"Next month''s priorities, written down before the month starts, so nothing in the following recap is a surprise. It also gives you somewhere to push back before the work happens rather than after.","nextExample":"Next: the two service pages with no dedicated content, then a citation audit."}'::jsonb, 1 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'example', 'recapExample', 'white', '{"eyebrow":"An Example","heading":"What a Recap Actually Looks Like","body":"The structure, drawn out. Every line below describes the kind of thing a recap contains.","panelTitle":"Monthly Project Recap","panelMeta":"Structure only. Not a real client report.","did":["Rewrote titles and meta descriptions for four priority service pages.","Corrected the business category and service list on the Google Business Profile.","Published one strategic SEO page for the highest-intent service term."],"why":["Those four pages already had impressions with no clear title, so they were the cheapest movement available.","The profile category was narrower than the services actually offered, which limits which searches it can appear for."],"changed":["Grid visibility for the primary service term, compared with last month.","Movement on the tracked keyword set, with the ones that moved named individually.","Where the month was quiet, the recap says so and says why."],"next":["The two service pages with no dedicated content.","A citation audit across the listings that carry an old address."],"caption":"An example of the structure, not a real client report. No figures appear in it because none of them would be real, and a page about honest reporting is the worst possible place for an invented number."}'::jsonb, 2 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'deliverables', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"What Arrives","heading":"What Arrives, and When","body":"Three deliverables, included in every package in both service lines.","cards":[{"title":"Monthly Reporting","icon":"bar-chart","body":"Detailed reporting on the work and the tracked keyword and competitor set. Traditional SEO packages add dashboard reporting on top of it."},{"title":"Monthly Project Recap","icon":"message-square","body":"Delivered by Loom or a video call. A person walking through what happened and answering questions, rather than a file dropped into an inbox."},{"title":"Quarterly Project Update","icon":"calendar","body":"A wider look every three months: what the quarter changed, what it taught, and where the next one is pointed."}]}'::jsonb, 3 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'standards', 'cardGrid', 'white', '{"variant":"numbered","columns":3,"eyebrow":"Editorial Discipline","heading":"What Gets Left Out","body":"A recap is more useful for what it leaves out than for what it piles in.","cards":[{"title":"Fewer Numbers, Better Ones","body":"A figure earns its place by informing a decision. Metrics that look impressive without changing what happens next are left out on purpose."},{"title":"Every Number Has a Reason","body":"Nothing appears in a recap without an explanation of why it is there and what it means. A number with no reading is decoration."},{"title":"Honest in Slow Months","body":"SEO has quiet months. When one happens, the recap says so, says why, and says what is being done about it."}]}'::jsonb, 4 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'by-lane', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"By Service","heading":"Reporting Differs by Where You Compete","body":"The four questions are the same in both lanes. What sits underneath them is not.","cards":[{"title":"Local SEO","icon":"map-pin","body":"Local search grid tracking, profile activity, review movement, and citation consistency. Visibility mapped across the service area rather than reduced to a single blended rank.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"Dashboard reporting, tracked keywords and competitors across markets, technical issues flagged as they appear, and how the strategic pages are performing.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 5 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Reporting Questions","items":[{"question":"How often do reports arrive?","answer":"A recap every month and a project update every quarter. Both are included in every package in both service lines, at every tier."},{"question":"Is the recap a document or a call?","answer":"A Loom video or a live video call, whichever suits you. Either way a person walks through the work rather than sending a file and hoping it gets read. Written reporting comes alongside it."},{"question":"What happens in a month where little moves?","answer":"The recap says so, and says why. SEO does not move in a straight line, and a report that reads like progress every single month is telling you less than one that admits a quiet stretch."},{"question":"Are rankings guaranteed?","answer":"No, and anyone guaranteeing them is guessing. What is guaranteed is the scope, the reporting, and knowing exactly what was done and why."},{"question":"Who else can see the reports?","answer":"Your call. The recap and the reporting are yours to share internally with whoever needs them, and the video format tends to make that easier rather than harder."},{"question":"What tools are used?","answer":"A mix of rank and grid tracking, Google Search Console, Google Analytics, and technical crawling. The tools matter less than the reading of them, which is the part the recap is for."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 6 from public.pages where slug = '/seo-reporting';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"See What the First Report Would Say","body":"A visibility review covers where you appear now, what is holding it back, and which of those is worth acting on first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 7 from public.pages where slug = '/seo-reporting';

-- Google Business Profile Optimization
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Google Business Profile Optimization","heading":"Your Google Business Profile Is Doing More Work Than Your Website","body":"For most local searches the profile is what people see, read and act on, often without ever opening a website. Getting it right is the fastest visibility work available to a local business.","primaryCta":{"label":"Get a Free Visibility Audit","href":"#free-audit"},"secondaryCta":{"label":"Explore Local SEO","href":"/local-seo-services"},"showcase":[{"kind":"coverage","label":"What gets worked","title":"The Profile Itself","items":["Categories and services","Business information","Photos and posts","Reviews and replies"]},{"kind":"channels","label":"Where it shows","title":"Local Surfaces","items":["Map results","Local search","Profile panel"]}]}'::jsonb, 0 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'what-it-affects', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"Why It Matters","heading":"What the Profile Actually Affects","body":"Three things, none of which the website controls.","cards":[{"title":"Map Results","icon":"map-pin","body":"Where the business appears when somebody searches nearby. The profile is what is being ranked in that result, not the website behind it."},{"title":"First Impressions","icon":"storefront","body":"Hours, photos, services and reviews are read directly in the results. For a lot of searches that is the whole of what someone sees before deciding."},{"title":"Direct Actions","icon":"phone","body":"Calls, direction requests and website clicks all happen from the profile itself. A weak one loses those before a visit ever starts."}]}'::jsonb, 1 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'problems', 'cardGrid', 'white', '{"variant":"compact","columns":3,"eyebrow":"Sound Familiar","heading":"Common Profile Problems","body":"Most profiles have at least two of these. Several of them take minutes to fix and have been costing visibility for years.","cards":[{"title":"Incomplete Categories","icon":"list-checks","body":"Your primary category is wrong, or the secondary ones were never set. Categories decide which searches you are eligible for at all."},{"title":"Inconsistent Information","icon":"warning","body":"Your name, address or phone number disagrees with what other listings say. Search engines notice the disagreement even when customers do not."},{"title":"No Recent Activity","icon":"calendar","body":"Your profile has not been posted to in months. An inactive profile reads as an inactive business."},{"title":"Unanswered Reviews","icon":"message-square","body":"Reviews sitting without a reply, good ones as well as bad. The reply is read by everyone who arrives afterwards."},{"title":"Missing Services","icon":"file-text","body":"Your services and products are undefined, so the profile cannot match a search for something you genuinely do."},{"title":"No Visibility Tracking","icon":"search","body":"You have no way of knowing whether any of it is working, or where in your area you are visible and where you are not."}]}'::jsonb, 2 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'free-audit', 'auditForm', NULL, '{"eyebrow":"Free Visibility Audit","heading":"Get a Free Look at Your Profile","body":"A written audit of the profile and the site behind it, built on the same four headings as the monthly recap: what is there, why it matters, what is working and what is not, and what to do next.","covers":["Categories, services and business information","Listing consistency across the web","Profile activity, photos and reviews","Where the profile is visible across the service area"],"note":"No call required.","submitLabel":"Get a Free Visibility Audit","profileHelp":"Optional. Paste the map listing link if you have it handy.","source":"Free Visibility Audit"}'::jsonb, 3 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'what-jmc-does', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"The Work","heading":"What JMC Does to a Profile","body":"Three things once, and three things every month. Which of the two you need is the whole of the choice below.","groupLabels":[{"at":0,"label":"One-time foundation"},{"at":3,"label":"Ongoing every month"}],"cards":[{"title":"Profile Audit","icon":"clipboard-check","body":"A full review of the profile as it stands, against how people in your area actually search for what you do."},{"title":"Category & Services Setup","icon":"list-checks","body":"Primary and secondary categories set deliberately, with services and products defined so the profile can match real searches."},{"title":"NAP & Citation Consistency","icon":"shield-check","body":"Name, address and phone standardised, then corrected across the listings that carry an older version of them."},{"title":"Ongoing Profile Posts","icon":"pencil","body":"Regular posts through the month, so the profile stays active rather than going quiet after the setup work finishes."},{"title":"Review Requests & Replies","icon":"star","body":"Requests sent to real customers and replies written to what arrives, positive and negative alike. Nothing is fabricated or incentivised."},{"title":"Local Search Grid Tracking","icon":"map-pin","body":"Visibility measured across the service area rather than as one blended number, so you can see where the profile is strong and where it is not.","visual":"searchGrid"}]}'::jsonb, 4 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'two-ways', 'cardGrid', 'white', '{"variant":"cards","columns":2,"eyebrow":"Two Ways In","heading":"One-Time Setup, or Ongoing Management","body":"The foundation work can be bought once on its own. The monthly work only makes sense as an ongoing engagement.","cards":[{"title":"One-Time Setup","icon":"rocket","meta":"Neighborhood Launch Sprint, $799","body":"Completed within 30 days. Covers the profile audit and core optimization, a citation audit and a single standard for your business information, and a 30-day roadmap for the whole picture rather than the profile alone. Start monthly service within 30 days and the onboarding fee on any Local package is waived.","cta":{"label":"View Launch Sprints","href":"/launch-sprints"}},{"title":"Ongoing Management","icon":"layers","meta":"Local SEO packages, from $875 a month","body":"Monthly profile posts, review requests and replies, citation work, local search grid tracking, and the monthly recap that says what changed. The profile work sits inside the wider local engagement rather than beside it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}}],"cta":{"label":"Not sure which fits? Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'surface', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"Profile work is easy to do invisibly, which is exactly why it gets reported the same way as everything else.","did":"The posts published, the listings corrected, the reviews replied to, named individually.","why":"Why that work was the priority, and what it was expected to affect.","changed":"Grid visibility across the service area, compared with last month, including the quiet ones.","next":"What is queued for the coming month, written down before it starts.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 6 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Profile Questions","items":[{"question":"Is this the same as Google My Business?","answer":"Yes. Google renamed Google My Business to Google Business Profile, and a lot of people still search for the old name. It is the same listing and the same work."},{"question":"Can this be done without a monthly package?","answer":"Yes. The Neighborhood Launch Sprint covers the foundation work as a one-time engagement and finishes with a 30-day roadmap, with no obligation to continue into a monthly package afterwards."},{"question":"How long before the profile improves?","answer":"Some changes show up almost immediately: corrected categories, services, hours and information can be reflected within days. Movement in map rankings is slower and depends on how competitive your area is, which is why the reporting separates the two rather than blending them."},{"question":"Who owns the profile?","answer":"You do, always. JMC requests manager access to a profile you own and never takes ownership of one. If the engagement ends, access is removed and nothing has to be handed back, because it was never held."},{"question":"Can suspended or duplicate profiles be fixed?","answer":"Duplicates can usually be merged or removed. Suspensions vary: some are caused by fixable information problems and some are not, and nobody can promise reinstatement. What JMC will do is look at the cause honestly and tell you whether it is worth pursuing."},{"question":"Does this help a business with no storefront?","answer":"Yes. A service-area business hides its address and is ranked against the area it covers, which makes categories, service definitions and listing consistency do more of the work. JMC is a service-area business itself and does not publish a street address."}],"cta":{"label":"Get a Free Visibility Audit","href":"#free-audit"}}'::jsonb, 7 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With the Profile","body":"A visibility review covers the profile, the site behind it, and which of the two is holding the other back.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Launch Sprints","href":"/launch-sprints"}}'::jsonb, 8 from public.pages where slug = '/google-business-profile-optimization';

-- Industries
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroCentered', NULL, '{"eyebrow":"Industries","heading":"The Method Doesn''t Change With the Industry","body":"Eight sectors, one approach. What changes between them is the language buyers search in, how long they take to decide, and what a single lead is worth."}'::jsonb, 0 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'grid', 'industryGrid', 'surface', '{"eyebrow":"Where JMC Works","heading":"Eight Industries, Two Kinds of Buyer","body":"The grouping below is descriptive. It says who a business sells to, and nothing about which service it needs.","groups":[{"label":"Consumer & Community","cards":[{"title":"Home Services & Trades","body":"Trades and home service businesses that get found at the moment something breaks.","icon":"wrench","href":"/industries/home-services-trades"},{"title":"Healthcare & Wellness","body":"Practices and clinics where patients choose from a short list and book an appointment.","icon":"heart-pulse","href":"/industries/healthcare-wellness"},{"title":"Hospitality & Attractions","body":"Places people plan a visit to, from an evening out to a weekend away.","icon":"utensils","href":"/industries/hospitality-attractions"},{"title":"Professional Services","body":"Firms whose clients compare a shortlist before they ever make contact.","icon":"briefcase","href":"/industries/professional-services"}]},{"label":"Industrial & B2B","cards":[{"title":"Energy & Petrochemical","body":"Suppliers and service firms selling into plants, operators and procurement teams.","icon":"lightning","href":"/industries/energy-petrochemical"},{"title":"Maritime & Logistics","body":"Port, freight and marine operators whose customers are other businesses.","icon":"ship","href":"/industries/maritime-logistics"},{"title":"Commercial Construction & Infrastructure","body":"Contractors, civil firms and suppliers working on commercial and public projects.","icon":"hard-hat","href":"/industries/commercial-construction-infrastructure"},{"title":"Aerospace & Aviation","body":"Manufacturers, service providers and suppliers in a heavily qualified supply chain.","icon":"plane","href":"/industries/aerospace-aviation"}]}],"escapeHatch":"The method doesn''t change with the industry. If yours isn''t listed, it almost certainly still applies.","cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 1 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'the-method', 'featureSplit', 'white', '{"align":"left","eyebrow":"Pillar","heading":"What Stays the Same, and What Doesn''t","body":"The work is the same regardless of sector. The same audit, the same technical foundation, the same content approach, the same reporting. What changes is the search language buyers use, how long they take to decide, and what a single lead is worth.\n\nThat is a deliberate position rather than a gap. A specialist charges for pattern-matching from other clients in your sector, and JMC does not claim to have that yet. What it offers instead is a method that transfers, run on two tracks depending on whether a business competes in a defined area or across markets.","tableHeadings":["Stays the same","Varies by industry"],"tableRows":[{"cells":["Audit and technical foundation","The search language buyers actually use"]},{"cells":["On-page and content approach","How long the buying cycle runs"]},{"cells":["Reporting and recap structure","What a single lead is worth"]}],"groups":[],"cta":{"label":"Explore Local SEO","href":"/local-seo-services"}}'::jsonb, 2 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'surface', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 3 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Industry Questions","items":[{"question":"Does JMC specialise in a particular industry?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC cannot honestly offer yet. What it offers instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."},{"question":"What if an industry isn''t listed here?","answer":"The method still applies. The eight above are the sectors most common around the Houston area, not a list of what JMC is willing to work on. A visibility review is the fastest way to find out how the approach lands in yours."},{"question":"Which service fits?","answer":"Reach decides it, not size. A business competing for customers in a defined area is Local SEO, however many locations it runs. A business competing across markets or service lines is Traditional SEO."},{"question":"Does the industry change the price?","answer":"No. The packages are the same across every industry. Scope is what produces a custom quote, and scope is about reach and volume rather than sector."},{"question":"Does the industry change the work?","answer":"The priorities and the search language shift, sometimes a great deal. The method and the reporting do not."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 4 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 5 from public.pages where slug = '/industries';

-- Home Services & Trades
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Home Services & Trades","heading":"SEO for Home Services and Trades","body":"Home service searches are urgent, local, and mostly made on a phone. Getting found in that moment is a different problem from ranking for a term someone researches over a fortnight.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"roadmap","label":"Every engagement","title":"The Same Method","items":["Audit and technical foundation","On-page and content work","Visibility tracking","Monthly recap"]},{"kind":"coverage","label":"What changes","title":"Not the Method","items":["Search language","Buying cycle","Lead value"]}]}'::jsonb, 0 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"cards","columns":5,"eyebrow":"Who This Is For","heading":"Businesses Inside Home Services & Trades","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"HVAC & Climate Control","icon":"gauge","body":"Demand spikes with the weather and the searches that come with it are almost always urgent. Visibility has to already be there when the heat arrives."},{"title":"Power Washing & Exterior Cleaning","icon":"storefront","body":"A seasonal, price-comparable service where the first few businesses a homeowner finds usually get the quote requests."},{"title":"Roofing & Exterior Remodeling","icon":"home","body":"High-value jobs with a longer decision than most trades, and a spike in searches after every storm."},{"title":"Electrical & Plumbing Trades","icon":"lightning","body":"A split between emergency calls and planned work, and the two are searched for in completely different language."},{"title":"Landscaping & Tree Services","icon":"wrench","body":"Recurring and one-off work side by side, usually chosen within a tight drive-time radius."}]}'::jsonb, 1 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in the Trades","body":"Trades searches are mostly emergencies, and an emergency search behaves nothing like a considered one. Someone whose air conditioning has failed in August is on a phone, will call one of the first businesses they see, and will not open a second page of results. Storm damage does the same thing to roofing at a larger scale, and it happens with no notice.\n\nThe buying cycle is short, often minutes. That makes the map pack and the profile more valuable here than almost anywhere else, and it makes an incomplete listing an expensive problem rather than a tidy-up job. Competition is usually local, which is the good news: the field is the businesses inside the same drive-time radius, not every company in the state.","groups":[{"title":"Phone first, and often after hours","icon":"phone","body":"The searches that convert best arrive outside business hours and end in a tap on a phone number."},{"title":"Seasonal spikes with no warning","icon":"lightning","body":"Weather sets the calendar. Visibility has to be built before the spike, because there is no time to build it during one."},{"title":"Won or lost inside the map pack","icon":"map-pin","body":"For urgent work the profile carries more weight than the website, so the two have to agree with each other."}]}'::jsonb, 2 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a home services & trades business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Home Services & Trades Questions","items":[{"question":"How quickly can a trades business expect to see movement?","answer":"Local work tends to move faster than national search because the competing field is smaller, but there is no honest way to promise a date. Profile and listing corrections can show up within weeks; content and authority work is a longer arc, and the recap tells you which one you are watching each month."},{"question":"Does a service-area business without a storefront rank differently?","answer":"Yes. A service-area business hides its address and is ranked against the area it covers rather than a pin on a map, which makes the service area definition, the categories, and consistent listings do more of the work."},{"question":"Is it worth doing SEO if most work comes from referrals?","answer":"Usually. Referrals get searched for by name before anyone calls, and a weak profile or a thin website loses jobs that were already won. That is often the cheapest fix on the list."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in home services & trades?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/home-services-trades';

-- Healthcare & Wellness
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Healthcare & Wellness","heading":"SEO for Healthcare and Wellness Practices","body":"Patients research before they book, and they usually stop at the first practice that looks credible and close. Visibility and reputation do the work together here.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"roadmap","label":"Every engagement","title":"The Same Method","items":["Audit and technical foundation","On-page and content work","Visibility tracking","Monthly recap"]},{"kind":"coverage","label":"What changes","title":"Not the Method","items":["Search language","Buying cycle","Lead value"]}]}'::jsonb, 0 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"cards","columns":4,"eyebrow":"Who This Is For","heading":"Businesses Inside Healthcare & Wellness","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"Dental Practices","icon":"heart-pulse","body":"One of the most competitive local categories anywhere, with searches split between routine care and urgent problems."},{"title":"Medical & Specialty Clinics","icon":"shield-check","body":"Often searched by condition rather than by specialty, which is rarely the language the practice uses about itself."},{"title":"Physical Therapy & Chiropractic","icon":"users","body":"Referral-heavy, but nearly every referral gets checked online before an appointment is made."},{"title":"Med Spas & Wellness Studios","icon":"star","body":"A discretionary purchase where reviews, photos and the profile carry as much weight as the website."}]}'::jsonb, 1 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Healthcare","body":"Patients search by symptom and by condition far more than by specialty. Somebody types what hurts, not the clinical name for the practitioner who fixes it, and the gap between those two vocabularies is where most practice websites lose traffic they should have had.\n\nThe cycle is short but not instant. A patient will usually look at two or three practices, check reviews on each, glance at photographs, and book the one that feels closest to both an answer and a location. That makes the profile, the reviews and the appointment path part of the SEO problem rather than separate from it. Competition is local and dense, particularly in dentistry, so the difference between the third and the first result is measured in booked appointments.","groups":[{"title":"Searched by symptom, not by specialty","icon":"search","body":"Content has to meet the language patients actually use before it can rank for it."},{"title":"Reviews are read before the site is","icon":"star","body":"Reputation and visibility are the same job here, which is why review support sits inside the packages."},{"title":"Booking friction undoes the ranking","icon":"calendar","body":"Being found first is worth little if the next step is a phone number and an answering machine."}]}'::jsonb, 2 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a healthcare & wellness business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Healthcare & Wellness Questions","items":[{"question":"Can a practice site rank without publishing medical advice?","answer":"Yes. Most of the useful traffic comes from service, condition and location pages describing what the practice treats and how a patient starts, rather than from clinical articles that need a physician to write and review them."},{"question":"How are patient reviews handled?","answer":"Packages include review request sends and replies. Nothing is fabricated or incentivised, and no review is ever written on a practice''s behalf, which would breach both the platform rules and the positioning this agency is built on."},{"question":"Does a multi-location practice need separate pages?","answer":"Usually yes. Each location needs its own profile, its own consistent listings, and enough of its own content that the two locations are not competing with each other in the same results."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in healthcare & wellness?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/healthcare-wellness';

-- Hospitality & Attractions
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Hospitality & Attractions","heading":"SEO for Hospitality and Attractions","body":"Hospitality search runs on two clocks at once: someone deciding where to eat in ten minutes, and someone planning a visit six weeks out. The same business has to be visible in both.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"roadmap","label":"Every engagement","title":"The Same Method","items":["Audit and technical foundation","On-page and content work","Visibility tracking","Monthly recap"]},{"kind":"coverage","label":"What changes","title":"Not the Method","items":["Search language","Buying cycle","Lead value"]}]}'::jsonb, 0 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"cards","columns":4,"eyebrow":"Who This Is For","heading":"Businesses Inside Hospitality & Attractions","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"Hotels & Lodging","icon":"building","body":"Competing against booking platforms that outrank almost everyone, so direct visibility has to be earned in the gaps they leave."},{"title":"Restaurants & Bars","icon":"utensils","body":"Short-notice, heavily map-driven searches where photos, hours and the menu decide the click."},{"title":"Venues & Event Spaces","icon":"calendar","body":"A long, considered booking with a high value, researched across many sites before anyone makes contact."},{"title":"Attractions & Tours","icon":"compass","body":"Draws visitors from well outside the immediate area, which pulls the work beyond a single local radius."}]}'::jsonb, 1 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Hospitality","body":"Hospitality is two industries wearing one coat. A restaurant is found by someone standing on a street with ten minutes of patience, where hours, photographs and the map listing settle it before the website is opened. A venue or a hotel is found by someone planning weeks ahead, comparing options across a dozen tabs, and reading far more than a listing.\n\nThe second kind is where the reach question decides the service. A neighbourhood restaurant competes inside a few miles. A destination attraction or a wedding venue draws from a whole region and competes with businesses in other cities for the same visit, which is a different problem with a different set of pages behind it. Booking platforms sit on top of many of these results, so part of the work is finding the searches they do not dominate.","groups":[{"title":"Two clocks, one business","icon":"calendar","body":"Immediate searches and planned ones need different pages and different language."},{"title":"Photos and hours decide the click","icon":"image","body":"Profile content is not housekeeping here. It is the deciding factor on the highest-volume searches."},{"title":"Reach varies wildly by format","icon":"globe","body":"A local bar and a regional attraction are not the same engagement, which is why neither lane is assumed."}]}'::jsonb, 2 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a hospitality & attractions business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Hospitality Questions","items":[{"question":"Is this a local or a regional problem?","answer":"It depends on where guests come from. A neighbourhood restaurant is Local SEO. An attraction or venue that draws from across the region competes across markets, which points toward Traditional SEO. That question gets answered in the review rather than assumed from the category."},{"question":"Can SEO compete with the booking platforms?","answer":"Not by outranking them everywhere. It works by taking the searches they handle badly, particularly branded, specific and planning-stage queries, and by making the direct booking path the obvious one once someone has found you."},{"question":"How much does the Google Business Profile matter?","answer":"More than in almost any other sector. Hours, photographs, menu links and attributes are read directly in the results by people who never reach the website, so a stale profile costs visits outright."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in hospitality & attractions?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/hospitality-attractions';

-- Professional Services
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Professional Services","heading":"SEO for Professional Services Firms","body":"Professional services buyers research quietly and at length, then contact one or two firms. Most of the decision happens before anyone picks up a phone.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"roadmap","label":"Every engagement","title":"The Same Method","items":["Audit and technical foundation","On-page and content work","Visibility tracking","Monthly recap"]},{"kind":"coverage","label":"What changes","title":"Not the Method","items":["Search language","Buying cycle","Lead value"]}]}'::jsonb, 0 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"Who This Is For","heading":"Businesses Inside Professional Services","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"Legal Practices","icon":"shield-check","body":"Among the most competitive search categories that exists, with a lead value high enough to justify the fight."},{"title":"Accounting & Financial Services","icon":"bar-chart","body":"Strongly seasonal for some services and steady for others, with a long client relationship at the end of it."},{"title":"Consulting & Agencies","icon":"compass","body":"Sold on credibility and specificity, where a vague services page loses to a precise one every time."}]}'::jsonb, 1 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Professional Services","body":"Buyers here are cautious and largely invisible. They read, they compare, they check credentials, and they often visit a firm''s site several times over weeks without ever filling in a form. The consequence is that traffic and enquiries move on different timelines, and a report that only shows enquiries misses most of what changed.\n\nThe searches themselves are specific. People look for a practice area plus a place, or a situation described in plain language, and generic pages built around the firm rather than the problem do badly against them. Lead value is high, which changes the arithmetic: a small number of the right visitors is worth more than a large number of the wrong ones, and that is what the tracked keyword set should reflect.","groups":[{"title":"A long, quiet consideration","icon":"clipboard-check","body":"Several visits before contact is normal, so early traffic movement matters before enquiries do."},{"title":"Practice area plus place","icon":"search","body":"Specific pages for specific services beat one broad page that tries to hold all of them."},{"title":"Credibility is a ranking factor in practice","icon":"shield-check","body":"Named people, real detail and clear scope outperform anonymous copy for both readers and search engines."}]}'::jsonb, 2 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a professional services business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Professional Services Questions","items":[{"question":"Why do enquiries lag behind traffic in this sector?","answer":"Because the decision takes weeks and involves several visits. That is normal here, and it is one of the reasons the recap reports what changed in visibility as well as what came through the form."},{"question":"Does a firm need a page per service?","answer":"Generally yes. Clients search for a specific practice area, and a single page trying to cover six of them tends to rank for none of them well."},{"question":"Are results in a competitive practice area realistic?","answer":"In the most contested categories, progress usually starts on more specific searches rather than the broadest term. That is a slower route but a real one, and the reporting is explicit about which stage the work is at."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in professional services?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/professional-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/professional-services';

-- Energy & Petrochemical
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Energy & Petrochemical","heading":"SEO for Energy and Petrochemical Suppliers","body":"Buyers in this sector search by specification, not by adjective. The work is making a business findable in the exact technical language its customers already use.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"roadmap","label":"Every engagement","title":"The Same Method","items":["Audit and technical foundation","On-page and content work","Visibility tracking","Monthly recap"]},{"kind":"coverage","label":"What changes","title":"Not the Method","items":["Search language","Buying cycle","Lead value"]}]}'::jsonb, 0 from public.pages where slug = '/industries/energy-petrochemical';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"Who This Is For","heading":"Businesses Inside Energy & Petrochemical","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"Field & Industrial Services","icon":"hard-hat","body":"Contracted on capability and compliance, and often searched for during a turnaround or an outage."},{"title":"Equipment & Component Suppliers","icon":"factory","body":"Found by part number, specification and standard far more often than by company name."},{"title":"Engineering & Technical Consultancies","icon":"compass","body":"A long procurement cycle with several people involved, each searching for something different."}]}'::jsonb, 1 from public.pages where slug = '/industries/energy-petrochemical';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Energy","body":"The searches are technical and unglamorous. A procurement manager or an engineer types a specification, a standard, a material or a part number, and the pages that win are the ones that carry those terms in a form a search engine can read. Marketing language actively hurts here, because nobody is searching for a phrase like world-class solutions.\n\nThe cycle is long, often months, and rarely involves one person. An engineer shortlists, procurement checks compliance, and a manager approves, and each of those people arrives through a different search. Competition is regional and national rather than local, which is what puts most of this sector in the Traditional lane, though a small field-service business working one area is a genuine Local engagement.","groups":[{"title":"Specifications, not adjectives","icon":"code","body":"Standards, materials and part numbers are the search terms. Pages have to contain them plainly."},{"title":"Several searchers, one purchase","icon":"users","body":"Technical, compliance and commercial questions each need their own page rather than one overview."},{"title":"Months, not minutes","icon":"calendar","body":"A long cycle means early visibility work shows up in enquiries much later than it shows up in traffic."}]}'::jsonb, 2 from public.pages where slug = '/industries/energy-petrochemical';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a energy & petrochemical business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/energy-petrochemical';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/energy-petrochemical';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Energy & Petrochemical Questions","items":[{"question":"Does SEO work when there are only a handful of real buyers?","answer":"It can, because the value of one contract is high enough that a small number of the right visitors justifies the work. It also changes what gets tracked: a narrow, technical keyword set matters far more than total traffic."},{"question":"How is technical content produced without in-house expertise?","answer":"By working from your specifications, datasheets and existing documentation rather than inventing them. Nothing technical is published without your review, because a wrong specification on a page costs more than a missing one."},{"question":"Is this Local or Traditional SEO?","answer":"Usually Traditional, because buyers are spread across markets. A field-service business working one area is a Local engagement, and location count never decides it. Reach does."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in energy & petrochemical?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/energy-petrochemical';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/energy-petrochemical';

-- Maritime & Logistics
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Maritime & Logistics","heading":"SEO for Maritime and Logistics Operators","body":"Logistics buyers search by route, service and capability, often under time pressure. Being findable in that language is most of the job.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"roadmap","label":"Every engagement","title":"The Same Method","items":["Audit and technical foundation","On-page and content work","Visibility tracking","Monthly recap"]},{"kind":"coverage","label":"What changes","title":"Not the Method","items":["Search language","Buying cycle","Lead value"]}]}'::jsonb, 0 from public.pages where slug = '/industries/maritime-logistics';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"Who This Is For","heading":"Businesses Inside Maritime & Logistics","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"Port & Terminal Services","icon":"ship","body":"Searched by service and by port, with capability and certification usually deciding the shortlist."},{"title":"Freight & Transport Operators","icon":"network","body":"Route and mode drive the search, and comparison against several operators is standard."},{"title":"Marine Repair & Fabrication","icon":"wrench","body":"Often urgent, because a vessel out of service is costing money every day it waits."}]}'::jsonb, 1 from public.pages where slug = '/industries/maritime-logistics';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Logistics","body":"Logistics search sits between the urgency of a trade and the caution of a procurement purchase. A freight buyer looking for a route and a mode will compare several operators before making contact, but a vessel needing repair is an emergency with a daily cost attached, and those two searches want completely different pages.\n\nThe vocabulary is precise. Routes, ports, vessel types, cargo classes and certifications are the terms people use, and a site organised around company departments rather than around those terms is hard to find no matter how good the business is. Reach varies enormously: a single-yard repair business competes locally, while a freight operator moving cargo across the region competes with operators in other cities for the same contract.","groups":[{"title":"Route, mode, capability","icon":"network","body":"Pages organised by what customers ship and where, rather than by internal department."},{"title":"Downtime makes some searches urgent","icon":"warning","body":"Repair and emergency service searches behave like a trade call, and need to be treated that way."},{"title":"Certifications are search terms","icon":"shield-check","body":"Compliance and accreditation are often the filter, so they belong on the page rather than in a PDF."}]}'::jsonb, 2 from public.pages where slug = '/industries/maritime-logistics';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a maritime & logistics business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/maritime-logistics';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/maritime-logistics';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Maritime Questions","items":[{"question":"Do customers really find logistics providers through search?","answer":"For new suppliers and for urgent requirements, frequently. Long-standing contracts come through relationships, but the shortlist for a new route or an unplanned repair is very often built from a search."},{"question":"Should pages be built around routes or around services?","answer":"Both, usually, because they are searched differently. A service page explains capability; a route or port page catches the searches that name a specific place."},{"question":"How is an urgent repair enquiry handled differently?","answer":"Those searches need a fast, obvious path to a phone number and clear coverage information, which is closer to how a trades page works than to how a procurement page works."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in maritime & logistics?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/maritime-logistics';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/maritime-logistics';

-- Commercial Construction & Infrastructure
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Commercial Construction & Infrastructure","heading":"SEO for Commercial Construction Firms","body":"Commercial construction is won on capability, references and bid lists, but the shortlist is increasingly built by searching. Being on it starts with being findable.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"roadmap","label":"Every engagement","title":"The Same Method","items":["Audit and technical foundation","On-page and content work","Visibility tracking","Monthly recap"]},{"kind":"coverage","label":"What changes","title":"Not the Method","items":["Search language","Buying cycle","Lead value"]}]}'::jsonb, 0 from public.pages where slug = '/industries/commercial-construction-infrastructure';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"Who This Is For","heading":"Businesses Inside Commercial Construction & Infrastructure","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"General & Specialty Contractors","icon":"hard-hat","body":"Shortlisted on project type and sector experience long before any bid conversation happens."},{"title":"Civil & Infrastructure Firms","icon":"building","body":"Public and private procurement with long cycles and a heavy emphasis on qualification."},{"title":"Building Products & Materials Suppliers","icon":"layers","body":"Specified by architects and engineers, which means being found by product and standard rather than by brand."}]}'::jsonb, 1 from public.pages where slug = '/industries/commercial-construction-infrastructure';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Construction","body":"The searches that matter here rarely look like lead generation. An architect looking for a product that meets a standard, a developer checking whether a contractor has done a project of a given type before, a procurement team qualifying a supplier: all of them are searching, and none of them will fill in a contact form on the first visit.\n\nThat makes the project and capability pages the working part of a construction site. Sector, project type, scale and qualification are the terms people search, and a portfolio organised as a photo gallery answers none of them. The cycle is measured in months, competition runs regional to national, and the value of a single project means a small volume of exactly the right visitors is the goal rather than traffic.","groups":[{"title":"Qualification, not enquiry","icon":"clipboard-check","body":"Most visitors are checking whether you qualify. The site has to answer that without a conversation."},{"title":"Project type is the search term","icon":"search","body":"Sector and project pages do the ranking. A gallery of photographs does not."},{"title":"Specified before it is bought","icon":"file-text","body":"For suppliers, the decision often happens with the specifier rather than with the buyer."}]}'::jsonb, 2 from public.pages where slug = '/industries/commercial-construction-infrastructure';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a commercial construction & infrastructure business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/commercial-construction-infrastructure';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/commercial-construction-infrastructure';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Construction Questions","items":[{"question":"Does SEO matter when work comes through bid lists?","answer":"Yes, because getting onto the list increasingly involves being found and checked first. Firms are researched before they are invited, and a thin website removes you from consideration quietly."},{"question":"What should a project portfolio actually contain?","answer":"Project type, sector, scale and scope written as text, not only photographs. That is what people search for, and images alone cannot be read as an answer to it."},{"question":"How long is the payback in this sector?","answer":"Longer than in consumer categories, because the cycle itself is long. The recap tracks visibility and qualification-stage movement in the meantime rather than pretending an enquiry count tells the whole story."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in commercial construction & infrastructure?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/commercial-construction-infrastructure';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/commercial-construction-infrastructure';

-- Aerospace & Aviation
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Aerospace & Aviation","heading":"SEO for Aerospace and Aviation Suppliers","body":"Aerospace buyers search by part, standard and certification, and they qualify before they contact. The work is being findable and credible in that order.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"roadmap","label":"Every engagement","title":"The Same Method","items":["Audit and technical foundation","On-page and content work","Visibility tracking","Monthly recap"]},{"kind":"coverage","label":"What changes","title":"Not the Method","items":["Search language","Buying cycle","Lead value"]}]}'::jsonb, 0 from public.pages where slug = '/industries/aerospace-aviation';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"Who This Is For","heading":"Businesses Inside Aerospace & Aviation","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"Parts & Component Manufacturers","icon":"factory","body":"Found by part number, material and specification, frequently by an engineer rather than a buyer."},{"title":"MRO & Ground Services","icon":"wrench","body":"Capability, certification and location together decide who gets contacted."},{"title":"Avionics & Systems Suppliers","icon":"code","body":"Highly technical searches, with compliance often acting as the first filter applied."}]}'::jsonb, 1 from public.pages where slug = '/industries/aerospace-aviation';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Aerospace","body":"Aerospace is the clearest example of search as qualification rather than as marketing. A procurement manager comparing specifications over six weeks is not going to be moved by a headline, and an engineer searching for a part number either finds a page carrying that number or does not. Certification is often the first filter applied, before capability and long before price.\n\nThe practical consequence is that the searchable surface of a supplier''s site is usually far too small. Capabilities live in a PDF, part ranges live in a table nobody can crawl, and approvals are named on an about page rather than where they would be searched for. Fixing that is unglamorous work with an unusually direct effect, and the competition for it is national rather than local.","groups":[{"title":"Certification filters first","icon":"shield-check","body":"Approvals belong on crawlable pages, not only inside a downloadable document."},{"title":"Part numbers are queries","icon":"search","body":"If a range only exists inside a PDF or a script-driven table, it cannot be found."},{"title":"Weeks of comparison before contact","icon":"calendar","body":"The site is doing the selling during a period when nobody is talking to you."}]}'::jsonb, 2 from public.pages where slug = '/industries/aerospace-aviation';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a aerospace & aviation business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/aerospace-aviation';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/aerospace-aviation';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Aerospace & Aviation Questions","items":[{"question":"Is search volume high enough to be worth the work?","answer":"Volume is low and value is very high, so the goal is not traffic. A narrow set of technical searches, found by the right handful of people, is what the tracked keyword set is built around."},{"question":"What about content that cannot be published?","answer":"Plenty in this sector is restricted, and none of it needs publishing. The gains usually come from making already-public capability, approvals and part information properly findable."},{"question":"Is a supplier competing locally or nationally?","answer":"Almost always nationally, which puts most aerospace suppliers in the Traditional lane. A ground services business tied to one airport is the exception, and it is a Local engagement."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in aerospace & aviation?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/aerospace-aviation';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/aerospace-aviation';

